// Webhook එකෙන් ආපු මුළු JSON data එකම ලබා ගැනීම
const webhookData = $input.item.json;

/* Chatbot එකෙන් (Telegram, WhatsApp, Facebook, or Custom chatbot) 
එන message එක සාමාන්‍යයෙන් තියෙන්නේ body එක ඇතුළේ.
පහතින් අපි බහුලවම එන විදි කිහිපයක් check කරනවා.
*/
const rawMessage = webhookData.body?.message || 
                     webhookData.body?.text || 
                     webhookData.body?.chatMessage || 
                     webhookData.query?.message;

// Message එකක් ඇවිත් නැත්නම් error එකක් නොවී handle කරන්න
const cleanMessage = rawMessage ? rawMessage.toString().trim() : "";

// AI Agent එකට කෙලින්ම පාවිච්චි කරන්න පුළුවන් විදිහට return කරනවා
return {
  json: {
    customerMessage: $input.first().json.body.chatInput,
    // AI එකට memory එක තියාගන්න Session ID එකකුත් අවශ්‍ය නම් පහතින් pass කරන්න පුළුවන්
    sessionId: webhookData.body?.senderId || webhookData.body?.chatId || $input.first().json.body.sessionId
  }
};

// Get the AI response
const aiResponse = $input.item.json;

// Extract text from response
let responseText = 'I apologize, but I encountered an error. Please contact our front desk at +94 45 2050973.';

if (aiResponse.output) {
  responseText = aiResponse.output;
} else if (aiResponse.text) {
  responseText = aiResponse.text;
} else if (aiResponse.content && Array.isArray(aiResponse.content)) {
  responseText = aiResponse.content
    .filter(item => item.type === 'text')
    .map(item => item.text)
    .join('\n');
}

return {
  response: $input.first().json.output,
  status: 'success',
  timestamp: new Date().toISOString()
};
